import React, { forwardRef } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import { CustomTimeframeSelector } from './CustomTimeframeSelector.js';
import { Presets } from './Presets.js';
import { timeframeSelectorOverlayCSS } from './TimeframeSelector.sty.js';
import type { TimeframeSelectorProps } from './TimeframeSelector.js';
import { Button } from '../../buttons/button/Button.js';
import { FocusScope } from '../../core/components/focus-scope/FocusScope.js';
import { OverlayContainer } from '../../core/components/OverlayContainer.js';
import { SharedInputPropsContext } from '../../core/contexts/SharedInputPropsContext.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import { OverlayStackingProvider } from '../../core/providers/OverlayStackingProvider.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import type { OverlayTriggerState } from '../../overlays/hooks/useOverlay.js';
import { DismissButton } from '../../overlays/hooks/useOverlay.js';
import type { OverlayProps } from '../../overlays/hooks/useOverlayWithTrigger.js';
import { Divider } from '../../typography/Divider.js';

//#region Typings
interface TimeframeSelectorOverlayProps
  extends WithChildren,
    Pick<TimeframeSelectorProps, 'onChange'> {
  /** The props of the overlay. */
  overlayProps: OverlayProps['overlayProps'];
  /** The state of the overlay. */
  overlayClose: OverlayTriggerState['close'];
  /**
   * Shows the "Clear selection" button if set to true.
   * @defaultValue false
   */
  clearable?: boolean;
}
//#endregion

/**
 * Relative Timeframe Selector Overlay component
 */
export const TimeframeSelectorOverlay = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TimeframeSelectorOverlayProps
>((props, forwardedRef) => {
  const { overlayProps, overlayClose, clearable, children, onChange } = props;
  const intl = useIntl();
  const { trapFocus, ...remainingOverlayProps } = overlayProps;
  const overlayContainerProps = useOverlayStacking(undefined, 'overlay');

  /** Handle clear selection and calls onChange */
  function handleClearSelection() {
    onChange?.(null);
  }

  return (
    <OverlayContainer {...overlayContainerProps}>
      <OverlayStackingProvider>
        <SharedInputPropsContext.Provider value={{}}>
          <FocusScope contain autoFocus>
            <Flex
              ref={forwardedRef}
              gap={4}
              flexDirection="column"
              aria-label={intl.formatMessage({
                defaultMessage:
                  'Timeframe selector overlay for providing a custom timeframe or selecting one of the presets',
                id: 'BcqdB7RacGy7tO8Z',
                description:
                  'Aria label for the overlay of the timeframe selector',
              })}
              className={timeframeSelectorOverlayCSS}
              {...remainingOverlayProps}
            >
              <Flex gap={4} flex={1} flexDirection="column" width="100%">
                <CustomTimeframeSelector />
                {children ?? <Presets />}
                {clearable && (
                  <>
                    <Divider />
                    <Flex
                      gap={4}
                      justifyContent="space-between"
                      paddingBottom={4}
                      paddingRight={4}
                      paddingLeft={4}
                    >
                      {/* Placeholder for the timezone that will be added later */}
                      <div></div>
                      <Button
                        data-testid="button-clear-selection-custom-timeframe"
                        type="reset"
                        onClick={handleClearSelection}
                      >
                        <FormattedMessage
                          defaultMessage="Reset timeframe"
                          id="EG+qZn4zIajJ41CP"
                          description="Shown for the reset timeframe button of the timeframe selector."
                        />
                      </Button>
                    </Flex>
                  </>
                )}
              </Flex>
              <DismissButton onDismiss={overlayClose} />
            </Flex>
          </FocusScope>
        </SharedInputPropsContext.Provider>
      </OverlayStackingProvider>
    </OverlayContainer>
  );
});

(
  TimeframeSelectorOverlay as typeof TimeframeSelectorOverlay & {
    displayName: string;
  }
).displayName = 'TimeframeSelectorOverlay';
